func main() {
    // yaml error tests
    tests := []string{
        "a: [unclosed\n",
        ":\n",
        "\tinvalid\n",
    }
    for _, s := range tests {
        var v interface{}
        err := yaml.Unmarshal([]byte(s), &v)
        fmt.Printf("yaml input %q err=%v\n", s, err)
    }
    // toml error tests
    tomlTests := []string{
        "a = [unclosed\n",
        "a: 1\n",
        "[[invalid\n",
        "a=1\na=2\n",
    }
    for _, s := range tomlTests {
        var v interface{}
        _, err := toml.Decode(s, &v)
        fmt.Printf("toml input %q err=%v\n", s, err)
    }
    // toml encode tests
    encodeTests := []map[string]interface{}{
        {"a": 1},
        {"a": map[string]interface{}{"b": 1}},
        {"a": []interface{}{map[string]interface{}{"b": 1}}},
    }
    for _, m := range encodeTests {
        var buf bytes.Buffer
        err := toml.NewEncoder(&buf).Encode(m)
        fmt.Printf("toml encode %#v err=%v out=%q\n", m, err, buf.String())
        // try with indent?
    }
    // yaml marshal tests
    ytests := []interface{}{
        map[string]interface{}{"a": 1},
        map[string]interface{}{"123": 1},
        map[string]interface{}{"a": "hello world"},
    }
    for _, m := range ytests {
        b, err := yaml.Marshal(m)
        fmt.Printf("yaml marshal %#v err=%v out=%q\n", m, err, string(b))
    }
}
EOF
