package main

import (
 "fmt"
 "gopkg.in/yaml.v3"
 "encoding/json"
 "github.com/BurntSushi/toml"
 "bytes"
)

func main() {
    // test marshaling float64(1.0) vs int
    for _, v := range []interface{}{int(1), int64(1), float64(1), float64(1.5)} {
        b, _ := json.Marshal(map[string]interface{}{"a": v})
        fmt.Printf("json marshal %#v (%T) => %s\n", v, v, string(b))
        yb, _ := yaml.Marshal(map[string]interface{}{"a": v})
        fmt.Printf("yaml marshal %#v (%T) => %q\n", v, v, string(yb))
        var buf bytes.Buffer
        toml.NewEncoder(&buf).Encode(map[string]interface{}{"a": v})
        fmt.Printf("toml marshal %#v (%T) => %q\n", v, v, buf.String())
    }
    // test json unmarshal
    for _, s := range []string{`{"a":1}`, `{"a":1.0}`, `{"a":1.5}`, `{"a":1e10}`} {
        var v interface{}
        dec := json.NewDecoder(bytes.NewBufferString(s))
        dec.UseNumber()
        // try without UseNumber
        var v2 interface{}
        json.Unmarshal([]byte(s), &v2)
        fmt.Printf("json unmarshal %q without UseNumber => %#v (%T)\n", s, v2.(map[string]interface{})["a"], v2.(map[string]interface{})["a"])
        dec.Decode(&v)
        fmt.Printf("json unmarshal %q with UseNumber => %#v (%T)\n", s, v.(map[string]interface{})["a"], v.(map[string]interface{})["a"])
    }
}
EOF
cd /tmp/gotest && GOPROXY=off GOSUMDB=off go run main.go 2>&1"}

