package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"math"
	"os"
	"reflect"
	"sort"
	"strconv"
	"strings"
	"time"

	"github.com/BurntSushi/toml"
	"gopkg.in/yaml.v3"
)

const versionStr = "v0.0.0"

func usage(prog string) string {
	return fmt.Sprintf(`Usage: %s [-][ytjcrneikhv]

Convert between YAML, TOML, JSON, and HCL.
Preserves map order.

-x[x]  Convert using stdin. Valid options:
          -yj, -y = YAML to JSON (default)
          -yy     = YAML to YAML
          -yt     = YAML to TOML
          -yc     = YAML to HCL
          -tj, -t = TOML to JSON
          -ty     = TOML to YAML
          -tt     = TOML to TOML
          -tc     = TOML to HCL
          -jj     = JSON to JSON
          -jy, -r = JSON to YAML
          -jt     = JSON to TOML
          -jc     = JSON to HCL
          -cy     = HCL to YAML
          -ct     = HCL to TOML
          -cj, -c = HCL to JSON
          -cc     = HCL to HCL
-n     Do not covert inf, -inf, and NaN to/from strings (YAML or TOML only)
-e     Escape HTML (JSON out only)
-i     Indent output (JSON or TOML out only)
-k     Attempt to parse keys as objects or numeric types (YAML out only)
-h     Show this help message
-v     Show version

`, prog)
}

func main() {
	prog := os.Args[0]
	// collect flags ignoring '-', ' ', '\t'
	var flagChars []rune
	for _, arg := range os.Args[1:] {
		for _, ch := range arg {
			if ch == '-' || ch == ' ' || ch == '\t' {
				continue
			}
			flagChars = append(flagChars, ch)
		}
	}
	validSet := map[rune]bool{
		'y': true, 't': true, 'j': true, 'c': true, 'r': true,
		'n': true, 'e': true, 'i': true, 'k': true, 'h': true, 'v': true,
	}
	var invalid []string
	for _, ch := range flagChars {
		if !validSet[ch] {
			invalid = append(invalid, string(ch))
		}
	}
	if len(invalid) > 0 {
		fmt.Fprint(os.Stderr, usage(prog))
		fmt.Fprintf(os.Stderr, "Error: invalid flags specified: %s\n", strings.Join(invalid, " "))
		os.Exit(1)
	}
	// determine conversion
	// expand r to j,y
	var conv []rune
	hasN, hasE, hasI, hasK, hasH, hasV := false, false, false, false, false, false
	for _, ch := range flagChars {
		switch ch {
		case 'y', 't', 'j', 'c':
			conv = append(conv, ch)
		case 'r':
			conv = append(conv, 'j', 'y')
		case 'n':
			hasN = true
		case 'e':
			hasE = true
		case 'i':
			hasI = true
		case 'k':
			hasK = true
		case 'h':
			hasH = true
		case 'v':
			hasV = true
		}
	}
	var inFmt, outFmt rune
	if len(conv) == 0 {
		inFmt, outFmt = 'y', 'j'
	} else if len(conv) == 1 {
		inFmt = conv[0]
		outFmt = 'j'
	} else {
		inFmt = conv[len(conv)-2]
		outFmt = conv[len(conv)-1]
	}
	// misuse checks: k > e > i
	if hasK && outFmt != 'y' {
		fmt.Fprint(os.Stderr, usage(prog))
		fmt.Fprint(os.Stderr, "Error: flag -k only valid for YAML output\n")
		os.Exit(1)
	}
	if hasE && outFmt != 'j' {
		fmt.Fprint(os.Stderr, usage(prog))
		fmt.Fprint(os.Stderr, "Error: flag -e only valid for JSON output\n")
		os.Exit(1)
	}
	if hasI && outFmt != 'j' && outFmt != 't' {
		fmt.Fprint(os.Stderr, usage(prog))
		fmt.Fprint(os.Stderr, "Error: flag -i only valid for JSON or TOML output\n")
		os.Exit(1)
	}
	if hasH {
		fmt.Fprint(os.Stdout, usage(prog))
		os.Exit(0)
	}
	if hasV {
		fmt.Fprintln(os.Stdout, versionStr)
		os.Exit(0)
	}
	// read stdin
	data, _ := io.ReadAll(os.Stdin)
	// dispatch
	var v Value
	var isEmptyYAML bool // for YAML empty (no doc) -> empty output
	var err error
	// parse
	switch inFmt {
	case 'y':
		v, isEmptyYAML, err = parseYAML(data)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error parsing YAML: %s\n", err.Error())
			os.Exit(1)
		}
		if isEmptyYAML {
			// empty output, no bytes
			os.Exit(0)
		}
	case 'j':
		v, err = parseJSON(data)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error parsing JSON: %s\n", err.Error())
			os.Exit(1)
		}
	case 't':
		v, err = parseTOML(data)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error parsing TOML: %s\n", err.Error())
			os.Exit(1)
		}
	case 'c':
		v, err = parseHCL(data)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error parsing HCL: %s\n", err.Error())
			os.Exit(1)
		}
	}
	// handle inf conversion pre-encoding? We'll do in encoders based on inFmt/outFmt/hasN
	var out []byte
	switch outFmt {
	case 'j':
		out, err = encodeJSON(v, inFmt, hasN, hasE, hasI)
		if err != nil {
			// JSON encoding should not error for Inf? We handle Inf via conversion, so no error expected
			fmt.Fprintf(os.Stderr, "Error writing JSON: %s\n", err.Error())
			os.Exit(1)
		}
	case 'y':
		out, err = encodeYAML(v, inFmt, hasN, hasK)
		if err != nil {
			// check if reflect error for null key?
			fmt.Fprintf(os.Stderr, "Error writing YAML: %s\n", err.Error())
			os.Exit(1)
		}
	case 't':
		out, err = encodeTOML(v, inFmt, hasN, hasI)
		if err != nil {
			// TOML write errors? Original uses "Error parsing TOML" for some? Let's see: for TOML write errors, what prefix?
			// Our earlier test showed TOML write for empty? No error. For now use "Error writing TOML" or "Error parsing TOML"?
			// Need to check: does TOML writing ever error? Possibly not for our cases. Use generic.
			fmt.Fprintf(os.Stderr, "Error writing TOML: %s\n", err.Error())
			os.Exit(1)
		}
	case 'c':
		out, err = encodeHCL(v, inFmt, hasN)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error writing HCL: %s\n", err.Error())
			os.Exit(1)
		}
	}
	if len(out) > 0 {
		os.Stdout.Write(out)
	}
	_ = hasN
	_ = reflect.TypeOf(nil)
	_ = sort.StringSlice{}
	_ = strconv.Itoa(0)
}

GOEOF
