package main

import (
	"bytes"
	"io"
	"time"

	"gopkg.in/yaml.v3"
)

func parseYAML(data []byte) (Value, bool, error) {
	dec := yaml.NewDecoder(bytes.NewReader(data))
	var node yaml.Node
	err := dec.Decode(&node)
	if err == io.EOF {
		return Value{}, true, nil
	}
	if err != nil {
		return Value{}, false, err
	}
	// node is DocumentNode, Content[0] is root
	if len(node.Content) == 0 {
		return Value{}, true, nil
	}
	root := node.Content[0]
	v, err := yamlNodeToValue(root)
	if err != nil {
		return Value{}, false, err
	}
	return v, false, nil
}

func yamlNodeToValue(n *yaml.Node) (Value, error) {
	switch n.Kind {
	case yaml.DocumentNode:
		if len(n.Content) == 0 {
			return NullValue(), nil
		}
		return yamlNodeToValue(n.Content[0])
	case yaml.SequenceNode:
		arr := make([]Value, 0, len(n.Content))
		for _, c := range n.Content {
			v, err := yamlNodeToValue(c)
			if err != nil {
				return Value{}, err
			}
			arr = append(arr, v)
		}
		return ArrayValue(arr), nil
	case yaml.MappingNode:
		kvs := make([]KV, 0, len(n.Content)/2)
		for i := 0; i < len(n.Content); i += 2 {
			kNode := n.Content[i]
			vNode := n.Content[i+1]
			kVal, err := yamlNodeToValue(kNode)
			if err != nil {
				return Value{}, err
			}
			vVal, err := yamlNodeToValue(vNode)
			if err != nil {
				return Value{}, err
			}
			kvs = append(kvs, KV{Key: kVal, Val: vVal})
		}
		return ObjectValue(kvs), nil
	case yaml.ScalarNode:
		return yamlScalarToValue(n)
	case yaml.AliasNode:
		// Alias should have been resolved? For anchors, AliasNode points to? Actually with Unmarshal, aliases are resolved?
		// For Decoder, AliasNode? Let's try to decode alias target
		// Fallback: treat as string?
		var v interface{}
		if err := n.Decode(&v); err != nil {
			return StringValue(n.Value), nil
		}
		return goToValue(v), nil
	default:
		// unknown, treat as string?
		return StringValue(n.Value), nil
	}
}

func yamlScalarToValue(n *yaml.Node) (Value, error) {
	// Use Decode to get Go value, which handles int/float/bool/null/time correctly
	var v interface{}
	// Need to handle custom tags? Decode will handle?
	// For !!binary, Decode gives string? Good.
	// For unknown tags like !custom, Decode gives string?
	if err := n.Decode(&v); err != nil {
		// fallback to string
		return StringValue(n.Value), nil
	}
	return goToValue(v), nil
}

func goToValue(v interface{}) Value {
	if v == nil {
		return NullValue()
	}
	switch x := v.(type) {
	case bool:
		return BoolValue(x)
	case int:
		return IntValue(int64(x))
	case int8:
		return IntValue(int64(x))
	case int16:
		return IntValue(int64(x))
	case int32:
		return IntValue(int64(x))
	case int64:
		return IntValue(x)
	case uint:
		return IntValue(int64(x))
	case uint8:
		return IntValue(int64(x))
	case uint16:
		return IntValue(int64(x))
	case uint32:
		return IntValue(int64(x))
	case uint64:
		if x > 9223372036854775807 {
			return FloatValue(float64(x))
		}
		return IntValue(int64(x))
	case float32:
		return FloatValue(float64(x))
	case float64:
		return FloatValue(x)
	case string:
		return StringValue(x)
	case time.Time:
		return TimeValue(x)
	case []interface{}:
		arr := make([]Value, len(x))
		for i, e := range x {
			arr[i] = goToValue(e)
		}
		return ArrayValue(arr)
	case map[string]interface{}:
		// order lost, but this path is for scalar decode? Actually mappings are handled via Node, not here.
		// For generic, convert with sorted keys? But should not happen for top-level? For safety, sort?
		kvs := make([]KV, 0, len(x))
		for k, vv := range x {
			kvs = append(kvs, KV{Key: StringValue(k), Val: goToValue(vv)})
		}
		// sort by key for determinism? Original preserves order, but here order lost. We'll sort to be deterministic.
		// Actually this case shouldn't happen for YAML mappings (handled via Node), only for nested? No, nested also via Node.
		// So this is fallback.
		return ObjectValue(kvs)
	case map[interface{}]interface{}:
		kvs := make([]KV, 0, len(x))
		for k, vv := range x {
			var kv Value
			// key could be any type
			kv = goToValue(k)
			kvs = append(kvs, KV{Key: kv, Val: goToValue(vv)})
		}
		return ObjectValue(kvs)
	default:
		// try reflection for other int types?
		return StringValuef("%v", x)
	}
}

func StringValuef(format string, a ...interface{}) Value {
	// helper
	return StringValue(sprintf(format, a...))
}

func sprintf(format string, a ...interface{}) string {
	// avoid importing fmt here? Use fmt.Sprintf
	// We'll import fmt in this file
	return fmtSprintf(format, a...)
}
