package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"strings"
)

func parseJSON(data []byte) (Value, error) {
	trimmed := bytes.TrimSpace(data)
	if len(trimmed) == 0 {
		return Value{}, fmt.Errorf("unexpected end of JSON input")
	}
	dec := json.NewDecoder(bytes.NewReader(data))
	dec.UseNumber()
	v, err := parseJSONValue(dec)
	if err != nil {
		return Value{}, err
	}
	// check trailing data
	// skip whitespace and check if more tokens?
	// Use raw remaining: try to decode next token, if EOF then ok, else error "invalid character 'X' after top-level value"
	// We need to find first non-whitespace char after first value.
	// Instead, try to decode another value: if dec.More() or next token not EOF?
	// Simplest: try to read next non-whitespace byte via dec.Buffered + remaining?
	// We'll manually check remaining bytes by re-encoding? Better: use json.RawMessage approach?
	// Alternative: after parsing first value, check if decoder has more data by trying Token with lookahead?
	// We'll read remaining via dec.Token() peek: if err==io.EOF then ok, else error.
	// But Token will skip whitespace and return next token or error.
	// For trailing " {"b":2}", next token would be '{', but our error should be "invalid character '{' after top-level value"
	// Token would return '{' delim without error, not the desired error. So we need to generate error ourselves.
	// Instead, we can check remaining bytes in the reader: dec.Buffered() + underlying?
	// Simpler: find position after first value by using json.Valid? Hmm.
	// Easiest: after parsing, read all remaining bytes from dec.Buffered() and underlying reader?
	// We'll just check if there is any non-whitespace left in original data after first value by using a second decoder that tries to decode?
	// Actually Go's json.Unmarshal does this check and produces that error. We can replicate by trying to unmarshal remaining?
	// Let's implement: get remaining data by reading from dec.InputOffset()? Go 1.14+ has InputOffset.
	offset := dec.InputOffset()
	rest := bytes.TrimSpace(data[offset:])
	if len(rest) > 0 {
		// first char
		ch := rest[0]
		// need to handle cases where rest starts with invalid? The error message uses the char.
		// For JSON, invalid character is quoted? e.g., "invalid character 'x' ..."
		// Use fmt with %q? Actually original: "invalid character 'x' after top-level value" where x is the char.
		// For control chars? We'll just use string(ch).
		return Value{}, fmt.Errorf("invalid character %q after top-level value", string([]byte{ch}))
		// Note: %q will produce single quotes? Actually fmt with %q for string gives double quotes. Need single quotes.
		// Go's error uses single quotes: 'x'. So we need to format as "'%c'"? Let's check: for '{', error is "invalid character '{' after..."
		// So format: "invalid character '%c' after top-level value" where %c is byte.
	}
	return v, nil
}

func parseJSONValue(dec *json.Decoder) (Value, error) {
	tok, err := dec.Token()
	if err != nil {
		return Value{}, err
	}
	switch t := tok.(type) {
	case json.Delim:
		switch t {
		case '{':
			var kvs []KV
			for dec.More() {
				// key
				ktok, err := dec.Token()
				if err != nil {
					return Value{}, err
				}
				keyStr, ok := ktok.(string)
				if !ok {
					return Value{}, fmt.Errorf("invalid character %v", ktok)
				}
				// value
				val, err := parseJSONValue(dec)
				if err != nil {
					return Value{}, err
				}
				kvs = append(kvs, KV{Key: StringValue(keyStr), Val: val})
				// Note: dec.More() handles comma
			}
			// consume '}'
			_, err := dec.Token()
			if err != nil {
				return Value{}, err
			}
			if kvs == nil {
				kvs = []KV{}
			}
			return ObjectValue(kvs), nil
		case '[':
			var arr []Value
			for dec.More() {
				val, err := parseJSONValue(dec)
				if err != nil {
					return Value{}, err
				}
				arr = append(arr, val)
			}
			_, err := dec.Token()
			if err != nil {
				return Value{}, err
			}
			if arr == nil {
				arr = []Value{}
			}
			return ArrayValue(arr), nil
		default:
			return Value{}, fmt.Errorf("invalid character %q", string(t))
		}
	case string:
		return StringValue(t), nil
	case json.Number:
		s := string(t)
		// decide int vs float
		if strings.ContainsAny(s, ".eE") {
			f, err := t.Float64()
			if err != nil {
				// fallback to float?
				return FloatValue(0), err
			}
			return FloatValue(f), nil
		}
		// try int64
		if i, err := t.Int64(); err == nil {
			return IntValue(i), nil
		}
		// overflow, try float
		f, err := t.Float64()
		if err != nil {
			return Value{}, err
		}
		return FloatValue(f), nil
	case float64:
		// without UseNumber, numbers are float64 (should not happen since we use UseNumber)
		return FloatValue(t), nil
	case bool:
		return BoolValue(t), nil
	case nil:
		return NullValue(), nil
	default:
		return Value{}, fmt.Errorf("invalid character %v", t)
	}
}
