func valueToYAMLNode(v Value, inFmt rune, hasN, hasK bool, isRoot bool) (*yaml.Node, error) {
	switch v.Kind {
	case KindNull:
		return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!null", Value: "null"}, nil
