			} else if s == "-Infinity" {
				return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!float", Value: "-.inf"}, nil
			} else if s == "NaN" {
				return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!float", Value: ".nan"}, nil
			}
		}
		return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!str", Value: s}, nil
	case KindTime:
		s := v.Time.UTC().Format(time.RFC3339)
		// Use timestamp tag? Or str? For YAML output, timestamps should be plain (not quoted). Use !!timestamp?
		return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!timestamp", Value: s}, nil
	case KindArray:
		n := &yaml.Node{Kind: yaml.SequenceNode, Tag: "!!seq"}
		for _, e := range v.Array {
			c, err := valueToYAMLNode(e, inFmt, hasN, hasK, false)
			if err != nil {
				return nil, err
			}
			n.Content = append(n.Content, c)
		}
		return n, nil
	case KindObject:
		n := &yaml.Node{Kind: yaml.MappingNode, Tag: "!!map"}
		for _, kv := range v.Object {
			var kNode *yaml.Node
			var err error
			if hasK {
				kNode, err = yamlKeyWithK(kv.Key, inFmt, hasN)
				if err != nil {
					return nil, err
				}
			} else {
				kNode, err = yamlKeyWithoutK(kv.Key)
				if err != nil {
					return nil, err
				}
			}
			vNode, err := valueToYAMLNode(kv.Val, inFmt, hasN, hasK, false)
			if err != nil {
				return nil, err
			}
			n.Content = append(n.Content, kNode, vNode)
		}
		return n, nil
	}
	return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!null", Value: "null"}, nil
}

func formatYAMLFloat(f float64) string {
