			return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!float", Value: "-.inf"}, nil
		} else if s == "NaN" {
			return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!float", Value: ".nan"}, nil
		}
	}
	return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!str", Value: s}, nil
}

func valueToYAMLNodeForKey(v Value, inFmt rune, hasN bool) (*yaml.Node, error) {
	// Convert parsed key Value to Node (for -k)
	// For string, check inf?
	if v.Kind == KindString {
		s := v.Str
		if (inFmt == 'j' || inFmt == 'c') && !hasN {
			if s == "Infinity" {
				return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!float", Value: ".inf"}, nil
			} else if s == "-Infinity" {
				return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!float", Value: "-.inf"}, nil
			} else if s == "NaN" {
				return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!float", Value: ".nan"}, nil
			}
		}
		return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!str", Value: s}, nil
	}
	// For other types, use valueToYAMLNode without -k (to avoid recursion)
	return valueToYAMLNode(v, inFmt, hasN, false)
}

func yamlKeyToStringForK(k Value) string {
	switch k.Kind {
	case KindString:
		return k.Str
	case KindInt:
		return strconv.FormatInt(k.Int, 10)
	case KindFloat:
		b, _ := json.Marshal(k.Float)
		return string(b)
	case KindBool:
		if k.Bool {
			return "true"
		}
		return "false"
	case KindNull:
		return "null"
	case KindTime:
		return k.Time.UTC().Format(time.RFC3339)
	case KindArray, KindObject:
		var buf bytes.Buffer
		writeJSONValue(&buf, k, 'y', false, false)
		return buf.String()
	default:
		return ""
	}
}

func tryParseJSONKey(s string) (interface{}, bool) {
	dec := json.NewDecoder(strings.NewReader(s))
	dec.UseNumber()
	var vv interface{}
	if err := dec.Decode(&vv); err != nil {
		return nil, false
	}
	offset := dec.InputOffset()
	rest := strings.TrimSpace(s[offset:])
	if len(rest) > 0 {
		return nil, false
	}
	if n, ok := vv.(json.Number); ok {
		str := string(n)
		if strings.ContainsAny(str, ".eE") {
			f, _ := n.Float64()
			return f, true
		}
		if i, err := n.Int64(); err == nil {
			return int64(i), true
		}
		f, _ := n.Float64()
		return f, true
	}
	return vv, true
}
