}

func encodeTOMLObject(buf *bytes.Buffer, kvs []KV, inFmt rune, hasN, hasI bool, prefix []string) {
	type item struct {
		key string
		val Value
		pos int
	}
	var prims []item
	var tables []item
	for idx, kv := range kvs {
		keyStr := tomlKeyToString(kv.Key, idx)
		if kv.Val.Kind == KindNull {
			continue
		}
		if kv.Val.Kind == KindObject {
			tables = append(tables, item{key: keyStr, val: kv.Val, pos: idx})
		} else if kv.Val.Kind == KindArray && len(kv.Val.Array) > 0 && allObjects(kv.Val.Array) {
			tables = append(tables, item{key: keyStr, val: kv.Val, pos: idx})
		} else {
			prims = append(prims, item{key: keyStr, val: kv.Val, pos: idx})
		}
	}
	for _, p := range prims {
		valStr, ok := encodeTOMLValue(p.val, inFmt, hasN)
		if !ok {
			continue
		}
		indent := ""
		if hasI && len(prefix) > 0 {
			indent = strings.Repeat("  ", len(prefix))
		}
		formattedKey := formatTOMLKey(p.key, p.pos)
		buf.WriteString(indent + formattedKey + " = " + valStr + "\n")
	}
	for _, t := range tables {
		fullPath := append(append([]string{}, prefix...), t.key)
		if t.val.Kind == KindObject {
			header := "[" + formatTOMLPath(fullPath) + "]"
			indent := ""
			if hasI && len(prefix) > 0 {
				indent = strings.Repeat("  ", len(prefix))
			}
			if buf.Len() > 0 {
				buf.WriteString("\n")
			}
			buf.WriteString(indent + header + "\n")
			encodeTOMLObject(buf, t.val.Object, inFmt, hasN, hasI, fullPath)
		} else if t.val.Kind == KindArray {
			for _, elem := range t.val.Array {
				header := "[[" + formatTOMLPath(fullPath) + "]]"
				indent := ""
				if hasI && len(prefix) > 0 {
					indent = strings.Repeat("  ", len(prefix))
				}
				if buf.Len() > 0 {
					buf.WriteString("\n")
