package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"math"
	"strconv"
	"strings"
)

func encodeHCL(v Value, inFmt rune, hasN bool) ([]byte, error) {
	if v.Kind != KindObject {
		// error with token type
		typ, val := hclTopToken(v)
		return nil, fmt.Errorf("Expected object, got unknown token: 1:1 %s %s", typ, val)
	}
	if len(v.Object) == 0 {
		return []byte{}, nil
	}
	var buf bytes.Buffer
	// Top-level: each KV separated by \n\n, no trailing newline?
	for idx, kv := range v.Object {
		if idx > 0 {
			buf.WriteString("\n\n")
		}
		// kv.Key must be string? For HCL output, keys always quoted? Even for numeric? Earlier {"123":1} to HCL gave "\"123\" = 1" (quoted). Good. So keys always quoted strings.
		// Convert Key Value to string for HCL? For String keys, use Str. For other types? For YAML with -k? No, -k only for YAML output, not HCL. So for HCL output, keys are always strings (since -k not applicable). Good. So kv.Key should be String. For safety, convert via hclKeyToString.
		keyStr := hclKeyToString(kv.Key)
		// Handle Val: if Val is Array where all elements are Objects? Need to handle table arrays vs single?
		// For HCL, arrays of objects are special: single-element unwrapped, multi-element repeated?
		// Actually for top-level, if Val is Array and all elements are Objects:
		// - if len==1, output as single object: "key" = { ... }
